B.Ox=new A.be("privacy_zuckering","Privacy Zuckering","Deceptive UI tricking users into sharing unintended data by making privacy settings confusing or misleading.","Tim Jones (2010)","Take time to review privacy settings instead of clicking 'Accept All'.",B.db,B.Qt,"",null,!1)
B.Qs=new A.ab(61941,"MaterialIcons",null,!1)
B.Om=new A.be("cliffhanger_engineering","Cliffhanger Engineering","Episodes mathematically structured to end mid-tension, forcing you to watch the next episode to resolve the psychological loop.","Streaming Platforms","Stop watching an episode in the middle of a scene rather than waiting for the end credits.",B.lj,B.Qs,"",null,!1)
B.Ps=new A.ab(57537,"MaterialIcons",null,!1)
B.OU=new A.be("frictionless_autoplay","Frictionless Autoplay","Removing the decision gap between content to enforce bingeing. The next video starts before you even realize you're watching it.","Netflix / YouTube","Turn off autoplay in your account settings.",B.lj,B.Ps,"",null,!1)
B.Q5=new A.ab(58710,"MaterialIcons",null,!1)
B.OT=new A.be("watch_time_optimisation","Watch Time Optimisation","Rewarding creators for duration over quality, resulting in padded content that artificially inflates your screen time.","Video Platform Algorithms","Use playback speed controls or skip ahead if content feels unnecessarily drawn out.",B.hy,B.Q5,"",null,!1)
